  font: 400 18px/1.6 'Newsreader', Georgia, serif; color: #BDB6C4;
}
/* The form: a plain ivory card */
form.card { grid-area: form; grid-row: 2 / span 3; margin: 128px 0 0; padding: 40px 36px 36px !important; border: 1px solid #E2D7C6 !important; border-radius: 12px; background: #F2EADD; box-shadow: none; }
.form-header::before { content: 'Tool 05  ·  Keyword ideas'; display: block; margin-bottom: 12px; font: 600 12px/1 'Instrument Sans', system-ui, sans-serif; letter-spacing: 1.6px; text-transform: uppercase; color: #5F59A8; }
